"""Sphinx configuration of the MR_AHA documentation.

The site has three kinds of pages:

* guides, written in Markdown (MyST) under ``source/``;
* the Python reference, generated by sphinx-autoapi from the docstrings of
  ``third_party/MR_AHA/python/mr_aha``. autoapi reads the source files and
  never imports the package, so no GPU and no built library are needed;
* the C reference, generated by Doxygen + Breathe from
  ``third_party/MR_AHA/include/mr_aha/mr_aha.h``, and the MATLAB reference,
  generated by ``tools/gen_matlab_api.py`` from the help blocks of
  ``third_party/MR_AHA/matlab/*.m``.

Doxygen and the MATLAB generator are run from this file, so
``sphinx-build -b html source _build/html`` is the whole build.
"""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parent
#: The library the reference pages are generated from: the pinned submodule,
#: or another checkout named by $MR_AHA_ROOT (handy while editing docstrings).
MR_AHA = Path(os.environ.get("MR_AHA_ROOT", REPO / "third_party" / "MR_AHA"))
if not (MR_AHA / "include" / "mr_aha" / "mr_aha.h").is_file():
    raise RuntimeError(
        f"MR_AHA sources not found in {MR_AHA}; run "
        "'git submodule update --init' or set MR_AHA_ROOT")

# -- Project ----------------------------------------------------------------

project = "MR_AHA"
author = "Junzhou Chen"
copyright = "2024-2026, Junzhou Chen"  # noqa: A001 - Sphinx's name

extensions = [
    "myst_parser",
    "sphinx.ext.napoleon",
    "sphinx.ext.mathjax",
    "sphinx.ext.githubpages",
    "autoapi.extension",
    "breathe",
    "sphinx_copybutton",
    "sphinx_design",
]
exclude_patterns = ["_build"]
#: Warn about every broken cross-reference.
nitpicky = False

# -- Markdown (MyST) --------------------------------------------------------

myst_enable_extensions = ["dollarmath", "amsmath", "colon_fence", "deflist"]
#: Anchors for headings down to level 3, so that pages can link to sections.
myst_heading_anchors = 3

# -- Python reference (sphinx-autoapi) --------------------------------------

autoapi_dirs = [str(MR_AHA / "python" / "mr_aha")]
autoapi_root = "api/python"
autoapi_add_toctree_entry = False
autoapi_member_order = "bysource"
autoapi_python_class_content = "both"
autoapi_options = ["members", "undoc-members", "show-inheritance",
                   "show-module-summary", "imported-members"]
#: The docstrings are Google style.
napoleon_google_docstring = True
napoleon_numpy_docstring = False
#: Render "Attributes:" as fields; autoapi already lists the attributes
#: themselves, and a second directive for each would be a duplicate.
napoleon_use_ivar = True

# -- C reference (Doxygen + Breathe) ----------------------------------------

DOXY_OUT = REPO / "doxygen"
DOXY_OUT.mkdir(exist_ok=True)
subprocess.run(
    ["doxygen", "-"], cwd=REPO, check=True,
    input=(REPO / "Doxyfile").read_text()
    + f"\nINPUT = {MR_AHA / 'include' / 'mr_aha'}\n"
    + f"OUTPUT_DIRECTORY = {DOXY_OUT}\n",
    text=True)
breathe_projects = {"mr_aha": str(DOXY_OUT / "xml")}
breathe_default_project = "mr_aha"
breathe_domain_by_extension = {"h": "c"}
#: "typedef enum mr_status {...} mr_status;" declares the enum and a typedef of
#: the same name, which the C domain reports as a duplicate declaration.
suppress_warnings = ["duplicate_declaration.c"]

# -- MATLAB reference -------------------------------------------------------

sys.path.insert(0, str(REPO / "tools"))
import gen_matlab_api  # noqa: E402

if gen_matlab_api.main(str(MR_AHA / "matlab"), str(HERE / "api" / "matlab")):
    raise RuntimeError("no MATLAB files found for the MATLAB reference")

# -- HTML -------------------------------------------------------------------

html_theme = "furo"
html_title = "MR_AHA"
html_static_path = ["_static"]
html_css_files = ["custom.css"]
html_favicon = "_static/favicon.svg"
html_theme_options = {
    "light_logo": "wordmark-light.svg",
    "dark_logo": "wordmark-dark.svg",
    "sidebar_hide_name": True,
    "source_repository": "https://github.com/mikecjz/MR_AHA_docs/",
    "source_branch": "main",
    "source_directory": "source/",
}
html_baseurl = "https://mikecjz.github.io/MR_AHA_docs/"
copybutton_prompt_text = r">>> |\$ "
copybutton_prompt_is_regexp = True
